/*
 * NVS Index Selection Logic
 * Priority order:
 * 1. CONFIG_NVS_TUYA: Defined in 'ti_drivers_config.h' via SysConfig (Best Practice).
 * 2. CUSTOM_TUYA_NVS_INDEX: Defined via compiler preprocessor flags.
 * 3. 0: Fallback default index (Risk: Assumes Tuya partition is always at index 0).
 */
#if defined(CONFIG_NVS_TUYA)
    // Ideal case: The header exists and the region is named 'CONFIG_NVS_TUYA' in SysConfig
    #define TUYA_NVS_INDEX CONFIG_NVS_TUYA

#elif defined(CUSTOM_TUYA_NVS_INDEX)
    // Manual override case: Set via project properties/compiler flags
    #define TUYA_NVS_INDEX CUSTOM_TUYA_NVS_INDEX

#else
    // Fallback case: Header missing or name not found. Defaulting to index 0.
    #define TUYA_NVS_INDEX 0
    
    // Optional: Warning message during compilation to remind developer
    // #pragma message("Warning: Using default NVS Index 0. Ensure Tuya NVS region is first.")
#endif

static NVS_Handle nvsHandle = NULL;
static NVS_Attrs regionAttrs;

// Helper to ensure NVS is open before operation
static OPERATE_RET _ensure_nvs_open(void) {
    if (nvsHandle != NULL) {
        return OPRT_OK;
    }

    NVS_init();
    
    // Open NVS using the determined index
    nvsHandle = NVS_open(TUYA_NVS_INDEX, NULL);

    if (nvsHandle == NULL) {
        return OPRT_COM_ERROR;
    }

    NVS_getAttrs(nvsHandle, &regionAttrs);
    return OPRT_OK;
}
// --- END: user defines and implements ---

/**
 * @brief read flash
 *
 * @param[in] addr: flash address
 * @param[out] dst: pointer of buffer
 * @param[in] size: size of buffer
 *
 * @note This API is used for reading flash.
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_flash_read(uint32_t addr, uint8_t *dst, uint32_t size)
{
    // --- BEGIN: user implements ---
    if (_ensure_nvs_open() != OPRT_OK) {
        return OPRT_COM_ERROR;
    }

    // NVS_read takes an offset from the region start. 
    // We assume 'addr' passed by Tuya is relative to the start of this partition.
    int_fast16_t status = NVS_read(nvsHandle, addr, dst, size);

    if (status != NVS_STATUS_SUCCESS) {
        return OPRT_COM_ERROR;
    }

    return OPRT_OK;
    // --- END: user implements ---
}

